import json
import re
from datetime import datetime

# Load the canonical dataset generated by build_canonical_dataset.py
with open('raw_drive_data/canonical_dataset.json', 'r', encoding='utf-8') as f:
    dataset = json.load(f)

print(f"Loaded canonical dataset with {len(dataset['activities'])} activities and {len(dataset['gnDivisions'])} GN divisions.")

# Generate activities in the exact format required by js/app.js
formatted_activities = []
photo_gallery = []

for a in dataset['activities']:
    act_id = a['id']
    gn_name = a['gnName']
    sabha_name = f"{gn_name} ප්‍රජා සංවර්ධන සභාව"
    
    # Image URLs for the activity
    image_urls = [p['full'] for p in a['photos']]
    
    # Build detailed activity object
    formatted_act = {
        "id": act_id,
        "titleSi": a['title'],
        "gnNameSi": gn_name,
        "sabhaNameSi": sabha_name,
        "date": a['date'],
        "dateRaw": a['dateRaw'],
        "locationSi": f"{gn_name} ග්‍රාම නිලධාරී වසම",
        "purposeSi": a['title'],
        "actionsSi": a['description'],
        "beneficiaries": "ප්‍රජා සාමාජිකයින් හා ගම්වාසීන්",
        "resultsSi": f"{a['categoryName']} සාර්ථකව නිමවා ප්‍රජා පහසුකම් පුළුල් කිරීම.",
        "progress": 100,
        "status": "completed",
        "statusLabelSi": "සම්පූර්ණයි",
        "category": a['categoryId'],
        "categoryNameSi": a['categoryName'],
        "categoryColor": a['categoryColor'],
        "categoryIcon": a['categoryIcon'],
        "budgetLKR": 0,
        "spentLKR": 0,
        "year": int(a['reportingMonth'][:4]),
        "monthSi": a['monthSi'],
        "reportingMonth": a['reportingMonth'],
        "images": image_urls,
        "photoCount": a['photoCount'],
        "duplicateCount": a['duplicateCount'],
        "flags": a['flags'],
        "shortDescSi": a['title'],
        "fullDescSi": a['description'],
        "source": a['source']
    }
    formatted_activities.append(formatted_act)
    
    # Add photos to photoGallery
    for p_idx, p in enumerate(a['photos'], 1):
        photo_id = f"PHOTO-{act_id}-{p_idx}"
        photo_gallery.append({
            "id": photo_id,
            "activityId": act_id,
            "titleSi": a['title'],
            "gnDivision": gn_name,
            "gnNameSi": gn_name,
            "sabhaNameSi": sabha_name,
            "date": a['date'],
            "year": int(a['reportingMonth'][:4]),
            "monthSi": a['monthSi'],
            "category": a['categoryId'],
            "categoryNameSi": a['categoryName'],
            "url": p['full'],
            "thumbnailUrl": p['thumbnail'],
            "driveUrl": p['driveUrl'],
            "driveId": p['id'],
            "captionSi": a['description'],
            "actionsSi": a['description'],
            "resultsSi": f"{a['categoryName']} සාර්ථකව නිම කිරීම.",
            "locationSi": f"{gn_name} ග්‍රාම නිලධාරී වසම",
            "beneficiaries": "ප්‍රජා සාමාජිකයින්",
            "progress": 100,
            "downloadable": True
        })

print(f"Total formatted activities: {len(formatted_activities)}")
print(f"Total photo gallery items: {len(photo_gallery)}")

# Peak dates calculation
date_counts = {}
for a in formatted_activities:
    if a['date']:
        date_counts[a['date']] = date_counts.get(a['date'], 0) + 1

peak_dates = []
for d, cnt in sorted(date_counts.items(), key=lambda x: x[1], reverse=True)[:10]:
    peak_dates.append({
        "date": d,
        "count": cnt,
        "labelSi": f"{d} ({cnt} වැඩසටහන්)"
    })

# Weekday distribution
weekday_order = ["සඳුදා", "අඟහරුවාදා", "බදාදා", "බ්‍රහස්පතින්දා", "සිකුරාදා", "සෙනසුරාදා", "ඉරිදා"]
weekday_analytics = [
    {
        "daySi": day,
        "count": dataset['weekdayDistribution'].get(day, 0),
        "pct": round(dataset['weekdayDistribution'].get(day, 0) / dataset['config']['totalProgrammes'] * 100, 1)
    }
    for day in weekday_order
]

# Calendar Heatmap Data (Daily activity dates)
daily_counts = {}
for a in formatted_activities:
    d_str = a['date']
    if d_str and len(d_str) == 10 and int(d_str[:4]) <= 2026:
        daily_counts[d_str] = daily_counts.get(d_str, 0) + 1

heatmap_data = []
for d_str in sorted(daily_counts.keys()):
    heatmap_data.append({
        "date": d_str,
        "count": daily_counts[d_str]
    })

